const webhookBody = $('Webhook Evaluate Quiz').first().json.body || {};
const quizDoc = $input.first().json;

if (!quizDoc || !Array.isArray(quizDoc.questions)) {
  throw new Error('QUIZ_NOT_FOUND: Belirtilen quiz_id veritabaninda bulunamadi.');
}

const userAnswers = webhookBody.answers || {};
const questions = quizDoc.questions;

let correctCount = 0;
const details = [];
const wrongQuestions = [];

questions.forEach((q) => {
  const qId = String(q.id);
  const userAnswer = String(userAnswers[qId] || '').trim();
  const correctAnswer = String(q.correct_answer || '').trim();
  const isCorrect = userAnswer === correctAnswer;

  if (isCorrect) {
    correctCount++;
  } else {
    wrongQuestions.push({
      question: q.question,
      user_answer: userAnswer || 'Boş bırakıldı',
      correct_answer: correctAnswer
    });
  }

  details.push({
    question_id: q.id,
    question: q.question,
    user_answer: userAnswer,
    correct_answer: correctAnswer,
    is_correct: isCorrect
  });
});

const totalQuestions = questions.length;
const score = totalQuestions > 0 ? Math.round((correctCount / totalQuestions) * 100) : 0;

return [
  {
    json: {
      quiz_id: webhookBody.quiz_id,
      title: quizDoc.title || 'Ders Testi',
      total_questions: totalQuestions,
      correct_count: correctCount,
      wrong_count: totalQuestions - correctCount,
      score,
      details,
      wrong_questions: wrongQuestions,
      created_at: new Date().toISOString()
    }
  }
];

