const evalData = $('Calculate Score & Wrong Topics').first().json;
const aiRaw = $input.first().json;

const feedback = String(
  aiRaw?.output ||
  aiRaw?.text ||
  aiRaw?.content ||
  aiRaw?.message?.content ||
  aiRaw?.response ||
  'Konu tekrarını tamamladıktan sonra testi yeniden çözebilirsin.'
).trim();

return [
  {
    json: {
      quiz_id: evalData.quiz_id,
      title: evalData.title,
      total_questions: evalData.total_questions,
      correct_count: evalData.correct_count,
      wrong_count: evalData.wrong_count,
      score: evalData.score,
      details: evalData.details,
      feedback,
      created_at: evalData.created_at
    }
  }
];
